import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {PublicNetworkError} from '../../research-v1/public-network.mjs';
import {digest} from '../../research-v3/model.mjs';
import {providerOrBrandResearchTarget} from '../../research-v3/research-target.mjs';
import {evaluateDirectProviderTruth,validateDirectProviderPage} from '../live/direct-provider-evidence.mjs';
import {replayProviderSeedCandidateReview,restoreProviderSeedCandidateReview} from '../live/provider-seed-authority-handoff.mjs';
import {autonomousProviderAuthorityDecision,providerRoutingAuthority} from '../live/provider-routing-authority.mjs';
import {admittedDiscoveryCandidate} from '../live/tavily-discovery.mjs';
import {createV2RobotsPublicAdapter} from '../live/robots-policy.mjs';
import {initializeAdaptiveState,runAdaptiveCampaign} from './adaptive-campaign.mjs';
import {providerSeedCampaignBounds,runProviderSeedCampaign} from './provider-seed-campaign.mjs';

const host='northstar.example',candidateUrl=`https://${host}/`,catalogUrl=`https://${host}/catalog`,market='DE';
const researchTarget=()=>providerOrBrandResearchTarget({seedName:'Northstar',targetMarket:market});
const service=(name,index=0)=>({'@type':'SoftwareApplication',name,description:'Consumer subscription service',offers:{'@type':'OfferCatalog',name:'Subscription plans',itemListElement:[{'@type':'Offer',name:'Monthly',priceSpecification:{'@type':'UnitPriceSpecification',price:12+index,priceCurrency:'EUR',billingDuration:'P1M',eligibleRegion:market}}]}});
const discoveryBody=(names,{complete=true}={})=>JSON.stringify({'@graph':names.map(service),...(complete?{subscriptionServiceCatalog:{scope:'PROVIDER_SUBSCRIPTION_SERVICES',coverage:'COMPLETE',serviceIds:names.map(name=>name.toLowerCase())}}:{})});
const authorityDiscoveryBody=(names,{complete=true,url=candidateUrl,provider='Northstar'}={})=>'<html><head><script type="application/ld+json">'+JSON.stringify({'@context':'https://schema.org','@graph':[{'@type':'Organization',name:provider,url},...names.map(service)],...(complete?{subscriptionServiceCatalog:{scope:'PROVIDER_SUBSCRIPTION_SERVICES',coverage:'COMPLETE',serviceIds:names.map(name=>name.toLowerCase())}}:{})})+'</script></head><body>'+provider+(names.length?'<a href="/catalog">Subscription pricing plans</a>':'')+'</body></html>';
const childBody=(id,index=0)=>JSON.stringify({serviceId:id,offers:[{id:id+'-monthly',amount:12+index,currency:'EUR',cadence:'MONTHLY',billingCadence:'MONTHLY',consumer:true,relationship:'SUBSCRIPTION',role:'ORDINARY',market}],catalog:{scope:'SERVICE_MARKET',coverage:'COMPLETE',market,offerIds:[id+'-monthly']}});
const page=(url,body,contentType=url===candidateUrl?'text/html':'application/json')=>({url,requestedUrl:url,outcome:'OK',httpStatus:200,contentType,truncated:false,body,sourceIntegrity:{sha256:digest(body)},accessDecisions:[{decision:'ALLOWED'}]});
const temp=t=>{const root=fs.mkdtempSync(path.join(os.tmpdir(),'provider-seed-campaign-'));t.after(()=>fs.rmSync(root,{recursive:true,force:true}));return root;};

function sizedBody(body,bytes){const size=Buffer.byteLength(body);assert(size<=bytes);return body+' '.repeat(bytes-size);}
function productionSizedRedirectAdapters({redirectBodyBytes,calls=[],networkCalls=[]}){
 const seed='Lattice',root='https://lattice.example/',regional='https://de.lattice.example/',fallback='https://directory.example/lattice',identity='<html><head><script type="application/ld+json">'+JSON.stringify({'@context':'https://schema.org','@graph':[{'@type':'Organization',name:'Lattice Labs',url:regional,brand:{'@type':'Brand',name:seed}}],subscriptionServiceCatalog:{scope:'PROVIDER_SUBSCRIPTION_SERVICES',coverage:'COMPLETE',serviceIds:[]}})+'</script></head><body>Lattice</body></html>',parentBody=sizedBody(identity,700),redirectBody=sizedBody(identity,redirectBodyBytes),providerBody=discoveryBody([]),robots='User-agent: *\nAllow: /\n';
 const createAdapters=async({stage})=>{assert.equal(stage,'PROVIDER_SEED');return {
  search:async()=>({results:[{url:root},{url:fallback}]}),
  read:async({url,role,maxBytes,stopOnCrossHostRedirect})=>{
   calls.push({url,role,maxBytes});const requested=url,reader=createV2RobotsPublicAdapter({authorities:[],retainRaw:true,maxLinks:20,maxReads:1,maxRequests:4,network:{maxBytes,maxRedirects:1,structuredJsonUrls:[regional],resolveHost:async()=>[{address:'93.184.216.34',family:4}],requestOnce:async request=>{
    const href=request.url.href;networkCalls.push({candidate:requested,url:href});if(request.url.pathname==='/robots.txt')return {status:200,headers:{'content-type':'text/plain'},body:Buffer.from(robots)};
    if(href===root)return {status:302,headers:{'content-type':'text/html',location:regional},body:Buffer.alloc(0)};
    assert.equal(href,regional);const body=role==='PROVIDER_SOURCE'?providerBody:requested===root?parentBody:redirectBody,type=role==='PROVIDER_SOURCE'?'application/json':'text/html',bytes=Buffer.byteLength(body);
    if(bytes>request.maxBytes)throw new PublicNetworkError('RESPONSE_TOO_LARGE',{stage:'DECLARED_LENGTH',limit:request.maxBytes,receivedBytes:0,declaredBytes:bytes,contentType:type});
    return {status:200,headers:{'content-type':type,'content-length':String(bytes)},body:Buffer.from(body)};
   }}});return reader.read({url,targetCountry:market,maxRedirects:1,stopOnCrossHostRedirect});
  }
 };};
 return {seed,root,regional,fallback,parentBody,redirectBody,providerBody,calls,networkCalls,createAdapters};
}

function adapters({names=['Orbit'],complete=true,calls=[],memoryRead=false}={}){
 return async ({stage})=>stage==='PROVIDER_SEED'?{
  search:async ({query})=>{calls.push({stage,route:'SEARCH',query});return {results:[{url:candidateUrl,title:'Northstar'}]};},
  read:async ({url,role})=>{calls.push({stage,route:'READ',url,role});assert.equal(url,candidateUrl);return page(candidateUrl,authorityDiscoveryBody(names,{complete}),'text/html');}
 }:{
  search:async ({query})=>{calls.push({stage,route:'SEARCH',query});return {results:[]};},
  read:async ({target})=>{calls.push({stage,route:'READ',service:target.service});const index=names.map(name=>name.toLowerCase()).indexOf(target.service);return page(catalogUrl,childBody(target.service,index));},
  consumeProvider:async args=>({...evaluateDirectProviderTruth({target:args.target,retained:validateDirectProviderPage(args)}),classification:'V3_NATIVE_PROVIDER_SOURCE',verified:[],blockers:[],monetary:1,needsGeo:false})
 };
}
const bindingUrl=()=>candidateUrl;

test('production-shaped provider seed autonomously reaches one KNOWN_SERVICE child and existing V3 Truth/catalog',async t=>{
 const directory=temp(t),calls=[],result=await runProviderSeedCampaign({directory,researchTarget:researchTarget(),createAdapters:adapters({calls})});
 assert.equal(result.providerAuthorityBinding.host,host);assert.equal(result.serviceDiscovery.status,'SERVICE_DISCOVERY_EXHAUSTED');assert.deepEqual(result.discoveredServices.map(row=>row.serviceId),['orbit']);assert.equal(result.children[0].target.service,'orbit');assert.equal(result.children[0].target.providerSeedAuthorityHandoff.service.serviceId,'orbit');
 assert.equal(Object.hasOwn(result.children[0].target,'marketProof'),false);assert.equal(Object.hasOwn(result.providerAuthorityBinding,'market'),false);const adaptiveTarget=result.adaptive.targets[result.children[0].targetId];assert.equal(providerRoutingAuthority(adaptiveTarget,catalogUrl).host,host);assert.equal(providerRoutingAuthority(adaptiveTarget,'https://billing.northstar.example/catalog'),null);
 assert.equal(result.lifecycle.results[0].offerings[0].ordinaryRecurringPrice.amount,12);assert.equal(result.lifecycle.results[0].catalog.state,'CATALOG_EXHAUSTED');assert.equal(result.lifecycle.complete,true);assert.equal(result.lifecycle.productionEligible,false);assert.equal(Object.hasOwn(result.researchTarget,'serviceId'),false);
 assert.deepEqual(calls.map(row=>row.route),['SEARCH','SEARCH','READ','READ']);assert.equal(result.lifecycle.usage.reads,2);assert.equal(result.lifecycle.usage.searches,2);assert.equal(result.adaptive.budgetScope,'CAMPAIGN');assert.equal(result.adaptive.initialUsage.reads,1);assert.equal(result.providerResourceReviews[0].status,'REUSED_CURRENT_CAMPAIGN');assert.equal(adaptiveTarget.reads[0].sameCampaignEvidenceReuse.bytes,0);assert.equal(adaptiveTarget.reads[0].networkGeography,'UNBOUND');assert.equal(adaptiveTarget.decisions.some(row=>row.currentCampaignEvidenceReuse&&row.acquisitionReserved),false);assert.equal(result.usage.countryAcquisitions,0);
});

