 const directory=temp(t),description='Northstar provides consumers access to digital magazines through its reading application.',authority=`<html><head><title>Northstar | Personal reading app subscription</title><meta property="og:title" content="Northstar | Personal reading app subscription"><link rel="canonical" href="${candidateUrl}"><meta property="og:url" content="${candidateUrl}"><meta name="description" content="${description}"><meta property="og:description" content="${description}"><meta property="og:type" content="website"></head><body><main><h1>Unlimited reading</h1></main></body></html>`,calls=[];
