 const factory=async({stage})=>stage==='PROVIDER_SEED'?{search:async()=>({results:[{url:candidateUrl}]}),read:async({url,role,maxBytes})=>{calls.push({url,role,maxBytes});if(url===candidateUrl)return page(candidateUrl,authority,'text/html');assert.equal(url,pricing);return page(pricing,discoveryBody(['Orbit']),'application/json');}}:{search:async()=>({results:[]}),read:async()=>assert.fail('child capacity is exhausted'),consumeProvider:async args=>({...evaluateDirectProviderTruth({target:args.target,retained:validateDirectProviderPage(args)}),classification:'V3_NATIVE_PROVIDER_SOURCE',verified:[],blockers:[],monetary:0,needsGeo:false})};
