test('general campaign capacity admits several ordinary provider documents under one monotonic aggregate bound',async t=>{
 const directory=temp(t),first=`https://${host}/plans-a`,second=`https://${host}/plans-b`,authority=sizedBody(authorityDiscoveryBody([],{complete:false}).replace('</body>','<a href="/plans-a">Subscription plans</a></body>'),320*1024),middle=sizedBody('<html><body><a href="/plans-b">Membership pricing</a></body></html>',395*1024),catalog=sizedBody(discoveryBody(['Orbit']),400*1024),calls=[];
 const factory=async({stage})=>stage==='PROVIDER_SEED'?{search:async()=>({results:[{url:candidateUrl}]}),read:async({url,role,maxBytes})=>{calls.push({url,role,maxBytes});if(url===candidateUrl)return page(url,authority,'text/html');if(url===first)return page(url,middle,'text/html');assert.equal(url,second);return page(url,catalog,'application/json');}}:{search:async()=>assert.fail('shared read capacity is exhausted'),read:async()=>assert.fail('children cannot multiply shared read capacity'),consumeProvider:async()=>({classification:'OFFLINE_CAPACITY_FIXTURE',verified:[],blockers:[],monetary:0,needsGeo:false})};
 const result=await runProviderSeedCampaign({directory,researchTarget:researchTarget(),createAdapters:factory,limits:{reads:3}}),sizes=[Buffer.byteLength(authority),Buffer.byteLength(middle),Buffer.byteLength(catalog)],total=sizes.reduce((sum,size)=>sum+size,0);
 assert.deepEqual(calls.map(row=>[row.url,row.role]),[[candidateUrl,'CANDIDATE_AUTHORITY_SOURCE'],[first,'PROVIDER_RESOURCE'],[second,'PROVIDER_RESOURCE']]);assert.deepEqual(calls.map(row=>row.maxBytes),[providerSeedCampaignBounds.bytes,providerSeedCampaignBounds.bytes-sizes[0],providerSeedCampaignBounds.bytes-sizes[0]-sizes[1]]);assert.deepEqual(result.providerResourceReviews.map(row=>row.status),['REUSED_CURRENT_CAMPAIGN','ACQUIRED','ACQUIRED']);assert.equal(result.providerResourceReviews[0].bytes,0);assert.deepEqual(result.providerResourceReviews.slice(1).map(row=>row.bytes),sizes.slice(1));assert.equal(result.usage.bytes,total);assert(total<providerSeedCampaignBounds.bytes);assert.equal(result.serviceDiscovery.bounds.bytes,providerSeedCampaignBounds.bytes);assert.deepEqual(result.discoveredServices.map(row=>row.serviceId),['orbit']);assert.equal(result.lifecycle.usage.bytes,total);assert.equal(result.lifecycle.usage.reads,3);
});

