 await assert.rejects(runProviderSeedCampaign({...input,onTransition:event=>{if(event==='CANDIDATES_DISCOVERED'&&!interrupted){interrupted=true;throw Error('SIMULATED_LEGACY_CHECKPOINT');}}}),/SIMULATED_LEGACY_CHECKPOINT/);const file=path.join(directory,'provider-seed-state.json'),legacy=JSON.parse(fs.readFileSync(file,'utf8'));delete legacy.discovery.activeCandidateIds;fs.writeFileSync(file,JSON.stringify(legacy));
 const result=await runProviderSeedCampaign(input);assert.equal(searches,2);assert.deepEqual(calls,[strong]);assert.equal(result.discovery.candidates.length,2);assert.equal(result.discovery.activeCandidateIds.length,1);assert(!result.discovery.activeCandidateIds.includes(result.candidateReviews[0].candidateId));assert.equal(result.usage.searches,2);assert.equal(result.usage.reads,1);assert.equal(result.usage.networkRequests,3);assert.equal(result.candidateReviews[0].status,'UNRESOLVED');
