 assert.deepEqual(calls.map(row=>row.url),[root,redirect,continuation]);assert.deepEqual(result.candidateReviews.map(row=>row.status),['REDIRECTED','UNRESOLVED','UNRESOLVED']);const redirectCandidate=result.discovery.candidates.find(row=>row.url===redirect),sourceCandidate=result.discovery.candidates.find(row=>row.url===continuation);
 assert.equal(result.candidateReviews[1].candidateId,redirectCandidate.candidateId);assert.equal(redirectCandidate.truthAuthority,'NONE');assert.equal(sourceCandidate.parentCandidateId,redirectCandidate.candidateId);assert.equal(sourceCandidate.truthAuthority,'NONE');assert.equal(result.providerAuthorityBinding,null);assert.equal(result.serviceDiscovery,null);
